    let score = 0;

    if (isInternalUtilityModel(name)) {
        score -= 200;
    }

    const priorityList = INTENT_MODEL_PRIORITIES[intent];
    const priorityIndex = priorityList.indexOf(name);
    if (priorityIndex >= 0) {
        score += (priorityList.length - priorityIndex) * 30;
    }

    if (intent === 'coding') {
        if (name.includes('coder') || name.includes('code')) {
            score += 14;
        }
        if (name.includes('qwen') || name.includes('deepseek') || name.includes('doubao-seed')) {
            score += 6;
        }
    }

    if (intent === 'reasoning') {
        if (name.includes('deepseek') || name.includes('kimi')) {
            score += 12;
        }
        if (name.includes('glm-5') || name.includes('m2.5')) {
            score += 5;
        }
    }

    if (intent === 'speed') {
        if (name.includes('glm-4.7') || name.includes('doubao_1_8')) {
            score += 10;
        }
        if (name.includes('qwen-3.5') || name.includes('m2') || name.includes('k2')) {
            score += 4;
        }
    }

    if (name.includes('preview') || name.includes('experimental')) {
        score -= 2;
    }

    return score;
}

function pickBestModel(models: string[], intent: ModelIntent): string | null {
    if (models.length === 0) {
        return null;
    }

    const nonInternal = models.filter(model => !isInternalUtilityModel(model));
    const pool = nonInternal.length > 0 ? nonInternal : models;

    let best: { name: string; score: number } | null = null;
    for (const model of pool) {
        const score = scoreModel(model, intent);
        if (!best || score > best.score) {
            best = { name: model, score };
        }
    }
    return best?.name ?? pool[0];
}

function safeStringify(value: unknown): string {
    try {
        return JSON.stringify(value);
    } catch {
        return String(value);
    }
}

function deepClone<T>(value: T): T {
    return JSON.parse(JSON.stringify(value)) as T;
}

function mutateModelFields(template: unknown, selectedModel: string): unknown {
    if (!template || typeof template !== 'object') {
        return template;
    }

    const copy = deepClone(template);
    const stack: unknown[] = [copy];
    while (stack.length > 0) {
        const current = stack.pop();
        if (!current || typeof current !== 'object') {
            continue;
        }
        if (Array.isArray(current)) {
            for (const item of current) {
                stack.push(item);
            }
            continue;
        }

        const obj = current as Record<string, unknown>;
        for (const [key, value] of Object.entries(obj)) {
            if (typeof value === 'string' && key.toLowerCase().includes('model')) {
                obj[key] = selectedModel;
            } else if (value && typeof value === 'object') {
                stack.push(value);
            }
        }
    }
    return copy;
}

function sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
}

function safeJsonParse(value: string): unknown | null {
    try {
        return JSON.parse(value);
    } catch {
        return null;
    }
}

function extractModelNamesFromJsonText(input: string, out: Set<string>): void {
    const regex = /"name":"([A-Za-z0-9][A-Za-z0-9._/-]{1,79})"/g;
    let match: RegExpExecArray | null = regex.exec(input);
    while (match) {
        const model = match[1];
        if (isLikelyModelName(model)) {
            out.add(model);
        }
        match = regex.exec(input);
    }
}

function extractModelNamesFromPayload(input: unknown, out: Set<string>): void {
    if (Array.isArray(input)) {
        for (const item of input) {
            extractModelNamesFromPayload(item, out);
        }
        return;
    }

    if (!input || typeof input !== 'object') {
        return;
    }

    const obj = input as Record<string, unknown>;
    const maybeName = obj.name;
    if (typeof maybeName === 'string' && isLikelyModelName(maybeName)) {
        out.add(maybeName);
    }

    for (const value of Object.values(obj)) {
        if (value && typeof value === 'object') {
            extractModelNamesFromPayload(value, out);
        }
    }
}

function extractSelectedModelFromPayload(input: unknown): string | null {
    if (!input || typeof input !== 'object' || Array.isArray(input)) {
        return null;
    }

    const obj = input as Record<string, unknown>;
    const maybeName = obj.name;
    if (typeof maybeName === 'string' && isLikelyModelName(maybeName)) {
        return maybeName;
    }

    const selectedModel = obj.selectedModel;
    if (selectedModel && typeof selectedModel === 'object' && !Array.isArray(selectedModel)) {
        const nested = selectedModel as Record<string, unknown>;
        const nestedName = nested.name;
        if (typeof nestedName === 'string' && isLikelyModelName(nestedName)) {
            return nestedName;
        }
    }

    return null;
}

function extractSelectedModelFromText(input: string): string | null {
    const match = /"name":"([A-Za-z0-9][A-Za-z0-9._/-]{1,79})"/.exec(input);
    if (!match) {
        return null;
    }
    return isLikelyModelName(match[1]) ? match[1] : null;
}

function resolveStateDbPaths(): string[] {
    const dedup = new Set<string>();
    const appData = process.env.APPDATA;
    if (appData) {
        dedup.add(path.join(appData, 'Trae CN', 'User', 'globalStorage', 'state.vscdb'));
        dedup.add(path.join(appData, 'Trae', 'User', 'globalStorage', 'state.vscdb'));
    }

    const homeDir = os.homedir();
    dedup.add(path.join(homeDir, '.config', 'Trae CN', 'User', 'globalStorage', 'state.vscdb'));
    dedup.add(path.join(homeDir, '.config', 'Trae', 'User', 'globalStorage', 'state.vscdb'));

    return Array.from(dedup.values()).filter(filePath => fs.existsSync(filePath));
}

function loadSqliteModule(): SqliteModuleLike | null {
    try {
        const candidate = require('node:sqlite') as Partial<SqliteModuleLike>;
        if (candidate && typeof candidate.DatabaseSync === 'function') {
            return candidate as SqliteModuleLike;
        }
    } catch {
        return null;
    }
    return null;
}

function readStateDbWithSqlite(dbPath: string, sqliteModule: SqliteModuleLike): StateDbProbeResult | null {
    let db: SqliteDatabaseLike | null = null;
    try {
        db = new sqliteModule.DatabaseSync(dbPath, { readonly: true });
        const rows = db.prepare(MODEL_LIST_SQL).all(
            STATE_DB_KEY_PATTERNS[0],
            STATE_DB_KEY_PATTERNS[1],
            STATE_DB_KEY_PATTERNS[2]
        );

        const modelSet = new Set<string>();
        let selectedModel: string | null = null;
        for (const row of rows) {
            const key = typeof row.key === 'string' ? row.key : '';
            const rawValue = typeof row.value === 'string' ? row.value : '';
            if (!rawValue) {
                continue;
            }

            const parsed = safeJsonParse(rawValue);
            if (parsed !== null) {
                extractModelNamesFromPayload(parsed, modelSet);
                if (key.includes('selected_model')) {
                    selectedModel = extractSelectedModelFromPayload(parsed) ?? selectedModel;
                }
            } else {
                extractModelNamesFromJsonText(rawValue, modelSet);
                if (key.includes('selected_model')) {
                    selectedModel = extractSelectedModelFromText(rawValue) ?? selectedModel;
                }
            }
        }

        const models = normalizeModelList(modelSet);
        if (models.length === 0) {
            return null;
        }

        return {
            models,
            selectedModel,
            sourcePath: dbPath,
            method: 'sqlite'
        };
    } catch {
        return null;
    } finally {
        try {
            db?.close?.();
        } catch {
            // ignore close failures
        }
    }
}

function readStateDbWithTextScan(dbPath: string): StateDbProbeResult | null {
    try {
        const content = fs.readFileSync(dbPath);
        const text = content.toString('utf8');
        const modelSet = new Set<string>();
        extractModelNamesFromJsonText(text, modelSet);
        const models = normalizeModelList(modelSet);
        if (models.length === 0) {
            return null;
        }
        return {
            models,
            selectedModel: null,
            sourcePath: dbPath,
            method: 'text-scan'
        };
    } catch {
        return null;
    }
}

function readStateDbModels(details: string[]): StateDbProbeResult | null {
    const dbPaths = resolveStateDbPaths();
    if (dbPaths.length === 0) {
        details.push('state.vscdb not found');
        return null;
    }

    const sqliteModule = loadSqliteModule();
    if (sqliteModule) {
        for (const dbPath of dbPaths) {
            const result = readStateDbWithSqlite(dbPath, sqliteModule);
            if (result) {
                details.push(`state.vscdb loaded via sqlite: ${result.sourcePath}`);
                return result;
            }
        }
        details.push('state.vscdb sqlite read failed');
    } else {
        details.push('node:sqlite unavailable');
    }

    for (const dbPath of dbPaths) {
        const result = readStateDbWithTextScan(dbPath);
        if (result) {
            details.push(`state.vscdb loaded via text scan: ${result.sourcePath}`);
            return result;
        }
    }

    details.push('state.vscdb text scan failed');
    return null;
}

async function executeCommandSafely(command: string, args: unknown[]): Promise<{ ok: boolean; value: unknown; error?: string }> {
    try {
        const value = await vscode.commands.executeCommand(command, ...args);
        return { ok: true, value };
    } catch (error) {
        return {
            ok: false,
            value: null,
            error: String(error)
        };
    }
}

async function autoSelectModel(payload: AutoSelectModelPayload): Promise<AutoSelectionResult> {
    const details: string[] = [];
    const prompt = (payload.prompt ?? '').trim();
    const intent = normalizeIntent(prompt, payload.modeHint);
    const candidateSet = new Set<string>();

    const allCommands = await vscode.commands.getCommands(true);
    const hasGetConfig = allCommands.includes('icube.extended.integrations.llm.getConfig');
    const hasSetConfig = allCommands.includes('icube.extended.integrations.llm.setConfig');
    const hasOpenPicker = allCommands.includes('workbench.action.chat.openModelPicker');

    details.push(`intent=${intent}`);
    details.push(`commands: getConfig=${hasGetConfig}, setConfig=${hasSetConfig}, openModelPicker=${hasOpenPicker}`);

    let currentConfig: unknown = null;
    if (hasGetConfig) {
        const configResult = await executeCommandSafely('icube.extended.integrations.llm.getConfig', []);
        if (configResult.ok) {
            currentConfig = configResult.value;
            collectModelCandidates(configResult.value, candidateSet);
            details.push('getConfig ok');
        } else {
            details.push(`getConfig failed: ${configResult.error}`);
        }
    }

    const stateDbResult = readStateDbModels(details);
    if (stateDbResult) {
        for (const model of stateDbResult.models) {
            candidateSet.add(model);
        }
        details.push(`state models=${stateDbResult.models.length}`);
        if (stateDbResult.selectedModel) {
            details.push(`state selected=${stateDbResult.selectedModel}`);
        }
    }

    const candidateModels = normalizeModelList(candidateSet);
    const selectedModel = pickBestModel(candidateModels, intent);
    if (!selectedModel) {
        if (hasOpenPicker) {
            await executeCommandSafely('workbench.action.chat.openModelPicker', []);
            details.push('no candidate models found; opened picker fallback');
        }
        return {
            intent,
            selectedModel: null,
            candidateModels,
            usedSetConfig: false,
            setConfigSucceeded: false,
            details: [...details, 'no model selected']
        };
    }

    details.push(`selected=${selectedModel}`);

    if (payload.dryRun) {
        return {
            intent,
            selectedModel,
            candidateModels,
            usedSetConfig: false,
            setConfigSucceeded: false,
            details: [...details, 'dryRun=true, no model switch attempted']
        };
    }

    if (!hasSetConfig) {
        if (hasOpenPicker) {
            await executeCommandSafely('workbench.action.chat.openModelPicker', []);
            details.push('setConfig missing, opened model picker as fallback');
        }
        return {
            intent,
            selectedModel,
            candidateModels,
            usedSetConfig: false,
            setConfigSucceeded: false,
            details
        };
    }

    const setConfigPayloads: unknown[] = [
        { model: selectedModel },
        { modelId: selectedModel },
        { modelName: selectedModel },
        { defaultModel: selectedModel },
        { activeModel: selectedModel },
        selectedModel
    ];
    if (currentConfig && typeof currentConfig === 'object') {
        setConfigPayloads.push(mutateModelFields(currentConfig, selectedModel));
    }

    let sawSetConfigOk = false;
    for (const config of setConfigPayloads) {
        const setRes = await executeCommandSafely('icube.extended.integrations.llm.setConfig', [config]);
        details.push(`setConfig tried: ${safeStringify(config)} -> ${setRes.ok ? 'ok' : setRes.error}`);
        if (!setRes.ok) {
            continue;
        }

        sawSetConfigOk = true;
        await sleep(120);

        const verifyState = readStateDbModels([]);
        const verifiedByState = verifyState?.selectedModel?.toLowerCase() === selectedModel.toLowerCase();
        if (verifiedByState) {
            details.push(`verify success: state selected=${verifyState?.selectedModel}`);
            return {
                intent,
                selectedModel,
                candidateModels,
                usedSetConfig: true,
                setConfigSucceeded: true,
                details
            };
        }
        if (verifyState?.selectedModel) {
            details.push(`verify state mismatch: ${verifyState.selectedModel}`);
        }

        if (hasGetConfig) {
            const verifyRes = await executeCommandSafely('icube.extended.integrations.llm.getConfig', []);
            if (verifyRes.ok && safeStringify(verifyRes.value).toLowerCase().includes(selectedModel.toLowerCase())) {
                details.push('verify success: selected model appears in getConfig');
                return {
                    intent,
                    selectedModel,
                    candidateModels,
                    usedSetConfig: true,
                    setConfigSucceeded: true,
                    details
                };
            }
            details.push(`verify getConfig: ${verifyRes.ok ? 'model not found' : verifyRes.error}`);
        }
    }

    if (hasOpenPicker) {
        await executeCommandSafely('workbench.action.chat.openModelPicker', []);
        details.push('all setConfig attempts unverified; opened picker fallback');
    }

    return {
        intent,
        selectedModel,
        candidateModels,
        usedSetConfig: sawSetConfigOk,
        setConfigSucceeded: false,
        details
    };
}

