- If existing project C:/Users/24228/Desktop/ai-auto-deepstremth/pretty-frontend-9999 is already available, you may continue there.
- Minimize unrelated changes.
- Complete all tasks now and apply edits directly.
`;

const ws = new WebSocket('ws://127.0.0.1:9090');
const events = [];
let commandStep = 0;

const commands = [
  { action: 'execute_command', waveId: 'B', taskId: 'B-cmd-newchat', retry: 0, command: 'workbench.action.chat.newChat', args: [] },
  { action: 'execute_command', waveId: 'B', taskId: 'B-cmd-agentmode', retry: 0, command: 'workbench.action.chat.toggleAgentMode', args: [] },
  { action: 'execute_command', waveId: 'B', taskId: 'B-cmd-openquickchat', retry: 0, command: 'workbench.action.openQuickChat', args: [] },
  { action: 'execute_command', waveId: 'B', taskId: 'B-cmd-typeprompt', retry: 0, command: 'type', args: [{ text: PROMPT }] },
  { action: 'execute_command', waveId: 'B', taskId: 'B-cmd-submit', retry: 0, command: 'workbench.action.chat.submitWithCodebase', args: [] }
];

const sendNext = () => {
  if (commandStep >= commands.length) return;
  const payload = commands[commandStep++];
  ws.send(JSON.stringify(payload));
};

const listenTimer = setTimeout(() => {
  const summary = {
    status: 'partial',
    message: 'dispatch done, listen window ended',
    command_results: events.filter(e => e.type === 'command_result'),
    file_saved_count: events.filter(e => e.type === 'file_saved').length,
    diagnostics_count: events.filter(e => e.type === 'system_diagnostics_report').length,
    recent_events: events.slice(-20)
  };
  console.log(JSON.stringify(summary, null, 2));
  try { ws.close(); } catch {}
  process.exit(0);
}, 90000);

ws.on('open', () => {
  sendNext();
});

ws.on('message', (raw) => {
  try {
    const msg = JSON.parse(raw.toString());
    if (msg.type === 'connected') {
      return;
    }

    events.push(msg);

    if (msg.type === 'command_result' && commandStep < commands.length) {
      setTimeout(sendNext, 300);
      return;
    }
  } catch (e) {
    events.push({ type: 'parse_error', error: String(e) });
  }
});

ws.on('error', (err) => {
  clearTimeout(listenTimer);
  console.log(JSON.stringify({ status: 'failed', message: 'ws error', error: err.message, events }, null, 2));
  process.exit(1);
});
